import 'dart:convert';
import 'dart:io';

import 'package:remix_cli/src/registry_source.dart' show validateRegistryPath;
import 'package:remix_cli/src/skills.dart' show SkillsIndex, skillsIndexPath;
import 'package:yaml/yaml.dart';

import 'install_pins.dart' show publishedSkillDirectories;

/// Skill subdirectories that are authoring data, not agent guidance.
///
/// `evals/evals.json` holds test prompts. An agent in a consumer project never
/// reads it, so it is not vendored.
const unpublishedSkillEntries = {'evals'};

const _header = '''
# Generated by tool/generate_skills_index.dart from the skill directories.
# Do not edit. Run `dart run melos run skills:index`; `docs:check` and
# registry promotion fail on drift.
#
# `remix skills install` reads this file at a project's pinned commit to learn
# which files make up each skill. `summary` is copied from the skill's
# agents/openai.yaml `interface.short_description`.
''';

/// Writes `skills/index.yaml`, the manifest `remix skills install` reads at a
/// pinned commit. Pass --check to fail on drift instead.
///
/// The raw-file host cannot list a directory, so a commit has to say which
/// files its skills contain. A generated file with a drift check says it
/// without anyone typing a file list.
void main(List<String> arguments) {
  final check = arguments.contains('--check');
  final unknown = arguments.where((argument) => argument != '--check');
  if (unknown.isNotEmpty) {
    stderr.writeln('Unsupported arguments: ${unknown.join(', ')}');
    exitCode = 64;
    return;
  }

  final workspaceRoot = Directory.current;
  final pubspec = File('${workspaceRoot.path}/pubspec.yaml');
  if (!pubspec.existsSync() ||
      !RegExp(
        r'^name:\s*remix_workspace\s*$',
        multiLine: true,
      ).hasMatch(pubspec.readAsStringSync())) {
    stderr.writeln('Run this generator from the workspace root.');
    exitCode = 64;
    return;
  }

  if (check) {
    final failures = checkSkillsIndex(workspaceRoot);
    if (failures.isNotEmpty) {
      failures.forEach(stderr.writeln);
      exitCode = 1;
      return;
    }
    stdout.writeln('$skillsIndexPath matches the skill directories.');
    return;
  }

  final String rendered;
  try {
    rendered = renderSkillsIndex(workspaceRoot);
  } on FormatException catch (error) {
    stderr.writeln(error.message);
    exitCode = 1;
    return;
  }
  File('${workspaceRoot.path}/$skillsIndexPath').writeAsStringSync(rendered);
  stdout.writeln('Wrote $skillsIndexPath.');
}

/// The manifest text for the skill directories under [workspaceRoot].
///
/// For each entry of [publishedSkillDirectories], in that order, `files` lists
/// every file under the directory except [unpublishedSkillEntries], as sorted
/// skill-relative POSIX paths with `SKILL.md` first, and `summary` is
/// `interface.short_description` from the skill's `agents/openai.yaml`, so the
/// one-line description has one author.
///
/// Throws a [FormatException] for a `skills/<name>/SKILL.md` that
/// [publishedSkillDirectories] does not list, for a skill without `SKILL.md`
/// or a `short_description`, a file that is not UTF-8 text, or a path the CLI
/// would reject. The CLI transport decodes text only, so a binary file must
/// fail here, in the repository, instead of in a user's project.
String renderSkillsIndex(Directory workspaceRoot) {
  for (final entity in Directory('${workspaceRoot.path}/skills').listSync()) {
    final skillPath =
        'skills/${entity.path.split(Platform.pathSeparator).last}';
    if (File('${entity.path}/SKILL.md').existsSync() &&
        !publishedSkillDirectories.contains(skillPath)) {
      throw FormatException(
        '$skillPath has a SKILL.md but is not in publishedSkillDirectories in '
        'tool/install_pins.dart.',
      );
    }
  }
  final buffer = StringBuffer(_header)
    ..writeln('schema: 1')
    ..writeln('skills:');
  for (final skillPath in publishedSkillDirectories) {
    final directory = Directory('${workspaceRoot.path}/$skillPath');
    final name = skillPath.split('/').last;
    if (!directory.existsSync()) {
      throw FormatException('$skillPath is missing.');
    }
    final files = <String>[];
    for (final entity in directory.listSync(recursive: true)) {
      if (entity is! File) continue;
      final relative = entity.path
          .substring(directory.path.length + 1)
          .replaceAll(Platform.pathSeparator, '/');
      if (unpublishedSkillEntries.contains(relative.split('/').first)) {
        continue;
      }
      validateRegistryPath('$skillPath/$relative');
      try {
        utf8.decode(entity.readAsBytesSync());
      } on FormatException {
        throw FormatException(
          '$skillPath/$relative is not UTF-8 text; remix skills install '
          'transfers text only.',
        );
      }
      files.add(relative);
    }
    if (!files.remove('SKILL.md')) {
      throw FormatException('$skillPath has no SKILL.md.');
    }
    files
      ..sort()
      ..insert(0, 'SKILL.md');
    buffer
      ..writeln('  $name:')
      ..writeln('    summary: ${jsonEncode(_summary(directory, skillPath))}')
      ..writeln('    files:');
    for (final file in files) {
      buffer.writeln('      - $file');
    }
  }
  final rendered = buffer.toString();
  SkillsIndex.parse(rendered);
  return rendered;
}

String _summary(Directory directory, String skillPath) {
  final metadata = File('${directory.path}/agents/openai.yaml');
  final Object? document = metadata.existsSync()
      ? loadYaml(metadata.readAsStringSync())
      : null;
  final interface = document is YamlMap ? document['interface'] : null;
  final summary = interface is YamlMap ? interface['short_description'] : null;
  if (summary is! String || summary.trim().isEmpty) {
    throw FormatException(
      '$skillPath/agents/openai.yaml has no interface.short_description.',
    );
  }
  return summary;
}

/// Empty when the committed manifest equals [renderSkillsIndex]; otherwise
/// one line that names the regenerate command.
List<String> checkSkillsIndex(Directory workspaceRoot) {
  final String expected;
  try {
    expected = renderSkillsIndex(workspaceRoot);
  } on FormatException catch (error) {
    return [error.message];
  }
  final committed = File('${workspaceRoot.path}/$skillsIndexPath');
  if (!committed.existsSync()) {
    return [
      '$skillsIndexPath is missing. Run `dart run melos run skills:index`.',
    ];
  }
  if (committed.readAsStringSync() != expected) {
    return [
      '$skillsIndexPath is stale. Run `dart run melos run skills:index`.',
    ];
  }
  return const [];
}
